method intersection(interval1: (int, int), interval2: (int, int)) returns (result: string)
    requires interval1.0 <= interval1.1 // start of first interval is less than or equal to end
    requires interval2.0 <= interval2.1 // start of second interval is less than or equal to end
    requires interval1.0 <= interval1.1 && interval2.0 <= interval2.1 // both intervals are valid

    // Preconditions to ensure the intervals intersect
    // Define the intersection points
    var startIntersection := max(interval1.0, interval2.0);
    var endIntersection := min(interval1.1, interval2.1);

    // Calculate the length of the intersection
    var lengthOfIntersection := endIntersection - startIntersection + 1; // +1 for closed intervals

    // Postconditions to define the expected outcome
    if lengthOfIntersection <= 0 {
        // If there's no intersection
        result := "NO";
    } else if isPrime(lengthOfIntersection) {
        result := "YES"; // If the length of intersection is prime
    } else {
        result := "NO"; // If the length of intersection is not prime
    }

    // Postcondition to ensure the result is either "YES" or "NO"
    assert result == "YES" || result == "NO";

    // Helper function to determine if a number is prime
    function isPrime(n: int) : bool
        requires n > 0
        ensures result == (forall i: int :: 2 <= i <= n / 2 ==> n % i != 0)
    {
        if n <= 1 {
            return false;
        }
        for i := 2 to n / 2 {
            if n % i == 0 {
                return false;
            }
        }
        return true;
    }
